import { test, expect } from '@playwright/test';
import { LoginPage } from '../pages/LoginPage';
import { DashboardPage } from '../pages/DashboardPage';
import { OTPPage } from '../pages/OTPPage';
import { BankingLoginTestData } from '../test-data/BankingLoginTestData';

test.describe('Banking Login Test Suite', () => {
  test.beforeEach(async ({ page, loginPage, dashboardPage, otpPage, testData }) => {
    // Step 1 — Open login page
    await test.step('Step 1 — Open login page', async () => {
      await page.goto(process.env.BASE_URL as string);
      await loginPage.validate();
    });
  });

  test.afterEach(async ({ page }, testInfo) => {
    if (testInfo.status !== testInfo.expectedStatus) {
      await page.screenshot({
        path: `${process.env.SCREENSHOT_DIR}/${testInfo.title}-${Date.now()}.png`,
      });
    }
  });

  test('TC_001: Login with valid username & password', async ({
    page,
    loginPage,
    dashboardPage,
    testData,
  }) => {
    // Step 2 — Enter valid username
    await test.step('Step 2 — Enter valid username', async () => {
      // TC_001_STEP_02
      await loginPage.enterUsername(testData.validUser.username);
    });

    // Step 3 — Enter valid password
    await test.step('Step 3 — Enter valid password', async () => {
      // TC_001_STEP_03
      await loginPage.enterPassword(testData.validUser.password);
    });

    // Step 4 — Click Login
    await test.step('Step 4 — Click Login', async () => {
      // TC_001_STEP_04
      await loginPage.clickLogin();
    });

    await test.step('Verify dashboard redirect', async () => {
      // TC_001_VER_01
      await expect(page).toHaveURL(/dashboard/);
      // TC_001_VER_01
      await expect(dashboardPage.getDashboardLocator()).toBeVisible();
    });
  });

  test('TC_002: Login with valid credentials + OTP', async ({
    loginPage,
    otpPage,
    dashboardPage,
    page,
    testData,
  }) => {
    // Step 5 — Enter valid credentials
    await test.step('Step 5 — Enter valid credentials', async () => {
      // TC_002_STEP_01
      await loginPage.enterUsername(testData.validUser.username);
      // TC_002_STEP_01
      await loginPage.enterPassword(testData.validUser.password);
    });

    // Step 6 — Click Login
    await test.step('Step 6 — Click Login', async () => {
      // TC_002_STEP_02
      await loginPage.clickLogin();
    });

    // Step 7 — Enter valid OTP
    await test.step('Step 7 — Enter valid OTP', async () => {
      const otp = await testData.getValidOTP();
      // TC_002_STEP_03
      await otpPage.enterOTP(otp);
    });

    // Step 8 — Submit
    await test.step('Step 8 — Submit', async () => {
      // TC_002_STEP_04
      await otpPage.clickSubmit();
    });

    await test.step('Verify secure redirect', async () => {
      // TC_002_VER_01
      await expect(page).toHaveURL(/dashboard/);
      // TC_002_VER_01
      await expect(dashboardPage.getDashboardLocator()).toBeVisible();
    });
  });

  test('TC_003: Invalid username', async ({
    loginPage,
    testData,
  }) => {
    // Step 9 — Enter invalid username and valid password
    await test.step('Step 9 — Enter invalid username and valid password', async () => {
      // TC_003_STEP_01
      await loginPage.enterUsername(testData.invalidUser.username);
      // TC_003_STEP_01
      await loginPage.enterPassword(testData.validUser.password);
      // TC_003_STEP_01
      await loginPage.clickLogin();
    });

    await test.step('Verify invalid-credentials error', async () => {
      // TC_003_VER_01
      await expect(loginPage.getErrorMessageLocator()).toHaveText(
        testData.errorMessages.invalidCredentials,
      );
    });
  });

  test('TC_004: Invalid password', async ({
    loginPage,
    testData,
  }) => {
    // Step 10 — Enter valid username and invalid password
    await test.step('Step 10 — Enter valid username and invalid password', async () => {
      // TC_004_STEP_01
      await loginPage.enterUsername(testData.validUser.username);
      // TC_004_STEP_01
      await loginPage.enterPassword(testData.invalidUser.password);
      // TC_004_STEP_01
      await loginPage.clickLogin();
    });

    await test.step('Verify invalid-password error', async () => {
      // TC_004_VER_01
      await expect(loginPage.getErrorMessageLocator()).toHaveText(
        testData.errorMessages.invalidCredentials,
      );
    });
  });

  test('TC_005: Both credentials invalid', async ({
    page,
    loginPage,
    testData,
  }) => {
    // Step 11 — Enter invalid credentials
    await test.step('Step 11 — Enter invalid credentials', async () => {
      // TC_005_STEP_01
      await loginPage.enterUsername(testData.invalidUser.username);
      // TC_005_STEP_01
      await loginPage.enterPassword(testData.invalidUser.password);
      // TC_005_STEP_01
      await loginPage.clickLogin();
    });

    await test.step('Verify login denied', async () => {
      // TC_005_VER_01
      await expect(page).toHaveURL(/login/);
      // TC_005_VER_01
      await expect(loginPage.getErrorMessageLocator()).toBeVisible();
    });
  });

  test('TC_006: Empty username', async ({
    loginPage,
    testData,
  }) => {
    // Step 12 — Leave username blank
    await test.step('Step 12 — Leave username blank', async () => {
      // TC_006_STEP_01
      await loginPage.enterPassword(testData.validUser.password);
      // TC_006_STEP_01
      await loginPage.clickLogin();
    });

    await test.step('Verify username validation', async () => {
      // TC_006_VER_01
      await expect(loginPage.getValidationMessageLocator()).toHaveText(
        testData.errorMessages.usernameRequired,
      );
    });
  });

  test('TC_007: Empty password', async ({
    loginPage,
    testData,
  }) => {
    // Step 13 — Leave password blank
    await test.step('Step 13 — Leave password blank', async () => {
      // TC_007_STEP_01
      await loginPage.enterUsername(testData.validUser.username);
      // TC_007_STEP_01
      await loginPage.clickLogin();
    });

    await test.step('Verify password validation', async () => {
      // TC_007_VER_01
      await expect(loginPage.getValidationMessageLocator()).toHaveText(
        testData.errorMessages.passwordRequired,
      );
    });
  });

  test('TC_008: Both fields empty', async ({ loginPage }) => {
    // Step 14 — Click login without input
    await test.step('Step 14 — Click login without input', async () => {
      // TC_008_STEP_01
      await loginPage.clickLogin();
    });

    await test.step('Verify required-field validation', async () => {
      // TC_008_VER_01
      await expect(loginPage.getValidationMessageLocator()).toBeVisible();
    });
  });
});